def normalizar_campos(registros):
    if not isinstance(registros, list):
        raise TypeError("registros deve ser uma lista")
    normalizados = []
    for reg in registros:
        if not isinstance(reg, dict):
            raise TypeError("cada registro deve ser um dicionário")
        novo = {}
        for k, v in reg.items():
            novo[k.lower().strip()] = str(v).strip()
        normalizados.append(novo)
    return normalizados


def ordenar_registros(registros, chave, direcao='asc'):
    if direcao not in ('asc', 'desc'):
        raise ValueError("direcao deve ser 'asc' ou 'desc'")
    if not registros:
        return []
    if not all(chave in r for r in registros):
        raise ValueError(f"chave '{chave}' ausente em algum registro")
    reverse = direcao == 'desc'
    return sorted(registros, key=lambda r: r[chave], reverse=reverse)

class Investimento:
    def __init__(self, capital: float, taxa_anual: float):
        if capital <= 0:
            raise ValueError("Capital deve ser positivo")
        if taxa_anual <= 0:
            raise ValueError("Taxa deve ser positiva")
        self.capital = capital
        self.taxa_anual = taxa_anual

    def valor_apos(self, anos: int) -> float:
        if anos < 0:
            raise ValueError("Anos não pode ser negativo")
        return self.capital * (1 + self.taxa_anual / 100) ** anos

    def tempo_para_dobrar(self) -> int:
        import math
        return math.ceil(math.log(2) / math.log(1 + self.taxa_anual / 100))

    def adicionar_aporte(self, valor: float) -> None:
        if valor <= 0:
            raise ValueError("Aporte deve ser positivo")
        self.capital += valor

def pares_soma_alvo(numeros, alvo):
    if not isinstance(numeros, list) or not all(isinstance(x, int) for x in numeros):
        raise ValueError("A lista deve conter apenas inteiros")
    if not isinstance(alvo, int):
        raise ValueError("O alvo deve ser um inteiro")

    from collections import Counter
    contagem = Counter(numeros)
    pares = []

    for a in sorted(contagem.keys()):
        b = alvo - a
        if a < b and b in contagem:
            qtd = min(contagem[a], contagem[b])
            pares.extend([(a, b)] * qtd)
        elif a == b:
            qtd = contagem[a] // 2
            pares.extend([(a, a)] * qtd)

    return pares

def corrente_ohm(tensao: float, resistencia: float) -> float:
