import hashlib
import hmac


def assinar_requisicao(chave_secreta: bytes, corpo: bytes, algoritmo: str = 'sha256') -> str:
    if not chave_secreta:
        raise ValueError("Chave secreta não pode ser vazia")
    if not corpo:
        raise ValueError("Corpo da requisição não pode ser vazio")
    try:
        construtor_hash = getattr(hashlib, algoritmo)
    except AttributeError:
        raise ValueError(f"Algoritmo '{algoritmo}' não suportado")
    assinatura = hmac.new(chave_secreta, corpo, construtor_hash).hexdigest()
    return assinatura

class ConversorBytes:
    """Converte um valor em bytes para KB, MB e GB (base 1024)."""

    def __init__(self, bytes_: int) -> None:
        if not isinstance(bytes_, int):
            raise TypeError("O valor deve ser um inteiro")
        if bytes_ < 0:
            raise ValueError("O valor em bytes não pode ser negativo")
        self._bytes = bytes_

    @property
    def bytes(self) -> int:
        return self._bytes

    @property
    def kb(self) -> float:
        return self._bytes / 1024

    @property
    def mb(self) -> float:
        return self._bytes / (1024 ** 2)

    @property
    def gb(self) -> float:
        return self._bytes / (1024 ** 3)

def analisar_texto(texto: str) -> tuple[int, int, float]:
    if not isinstance(texto, str):
        raise TypeError("A entrada deve ser uma string.")
    if not texto.strip():
        raise ValueError("O texto não pode ser vazio ou conter apenas espaços.")

    import re
    palavras = re.findall(r'\b\w+\b', texto)
    num_palavras = len(palavras)

    frases = re.split(r'[.!?]+', texto)
    num_frases = len([f for f in frases if f.strip()])

    if num_palavras == 0:
        media = 0.0
    else:
        media = round(sum(len(p) for p in palavras) / num_palavras, 1)

    return num_palavras, num_frases, media

class ContadorCategoria:
