def gerar_sequencia_logaritmica(inicio: float, razao: float, n: int) -> list[float]:
    if inicio <= 0:
        raise ValueError("inicio deve ser maior que zero")
    if razao <= 0 or razao == 1:
        raise ValueError("razao deve ser maior que zero e diferente de 1")
    if n < 1:
        raise ValueError("n deve ser maior ou igual a 1")
    sequencia = []
    termo = inicio
    for _ in range(n):
        sequencia.append(termo)
        termo *= razao
    return sequencia

def calcular_percentis_latencia(latencias: list[float], percentis: list[float]) -> dict[float, float]:
    if not latencias:
        raise ValueError("Lista de latências não pode ser vazia")
    if any(l < 0 for l in latencias):
        raise ValueError("Latências não podem ser negativas")
    if not percentis:
        raise ValueError("Lista de percentis não pode ser vazia")
    if any(p < 0 or p > 100 for p in percentis):
        raise ValueError("Percentis devem estar entre 0 e 100")

    sorted_lat = sorted(latencias)
    n = len(sorted_lat)
    resultado = {}
    for p in percentis:
        if p == 0:
            idx = 0
        else:
            pos = (p / 100) * n
            import math
            rank = math.ceil(pos)
            if rank < 1:
                rank = 1
            idx = rank - 1
        resultado[p] = sorted_lat[idx]
    return resultado

def calcular_pontuacao(nivel, inimigos_derrotados, itens_coletados, tempo_segundos):
    if nivel not in (1, 2, 3):
        raise ValueError("Nível deve ser 1, 2 ou 3")
    if inimigos_derrotados < 0:
        raise ValueError("Inimigos derrotados não pode ser negativo")
    if itens_coletados < 0:
        raise ValueError("Itens coletados não pode ser negativo")
    if tempo_segundos < 0:
        raise ValueError("Tempo não pode ser negativo")

    multiplicadores = {1: 1.0, 2: 1.5, 3: 2.0}
    base = 100 * multiplicadores[nivel]

    bonus_inimigos = 500 if inimigos_derrotados > 10 else 0
    bonus_itens = 300 if itens_coletados > 5 else 0

    penalidade = max(0, tempo_segundos - 60) * 10

    return int(base + bonus_inimigos + bonus_itens - penalidade)

class MaquinaRefrigerante:
    def __init__(self):
        self._estoque = {}
        self._precos = {}
        self._saldo = 0.0
        self._moedas_validas = {0.25, 0.50, 1.00, 2.00}

    def abastecer(self, produto: str, quantidade: int, preco: float):
        if quantidade <= 0 or preco <= 0:
            raise ValueError("Quantidade e preço devem ser positivos")
        if produto in self._estoque:
            self._estoque[produto] += quantidade
        else:
            self._estoque[produto] = quantidade
        self._precos[produto] = preco

    def inserir_moeda(self, valor: float):
        if valor not in self._moedas_validas:
            raise ValueError("Moeda inválida")
        self._saldo += valor

    def comprar(self, produto: str):
        if produto not in self._estoque:
            raise ValueError("Produto inexistente")
        if self._estoque[produto] <= 0:
            raise ValueError("Produto esgotado")
        preco = self._precos[produto]
        if self._saldo < preco:
            raise ValueError("Saldo insuficiente")
        self._estoque[produto] -= 1
        self._saldo = 0.0
        return produto

    def troco(self):
        troco = self._saldo
        self._saldo = 0.0
        return troco

    def estoque(self, produto: str):
        return self._estoque.get(produto, 0)

def pontuar_curriculo(dados: dict) -> int:
    chaves_obrigatorias = {"anos_experiencia", "nivel_educacao", "certificacoes"}
    if not chaves_obrigatorias.issubset(dados.keys()):
        raise ValueError("Chaves obrigatórias ausentes")

    anos = dados["anos_experiencia"]
    if not isinstance(anos, int) or anos < 0:
        raise ValueError("anos_experiencia deve ser inteiro não negativo")

    nivel = dados["nivel_educacao"]
    pontos_educacao = {
        "fundamental": 0,
        "medio": 5,
        "superior": 10,
        "mestrado": 15,
        "doutorado": 20,
    }
    if nivel not in pontos_educacao:
        raise ValueError("nivel_educacao inválido")

    certs = dados["certificacoes"]
    if not isinstance(certs, list):
        raise ValueError("certificacoes deve ser uma lista")
    for c in certs:
        if not isinstance(c, str) or c == "":
            raise ValueError("certificacoes deve conter apenas strings não vazias")

    pontos_exp = min(anos * 2, 20)
    pontos_edu = pontos_educacao[nivel]
    pontos_cert = min(len(certs) * 3, 15)

    return pontos_exp + pontos_edu + pontos_cert

import re
from collections import defaultdict


class RelatorioUso:
    def __init__(self):
        self._dados = defaultdict(lambda: defaultdict(int))

    def registrar(self, cliente: str, mes: str, minutos: int) -> None:
        if minutos < 0:
            raise ValueError("minutos não pode ser negativo")
        if not re.fullmatch(r"\d{4}-\d{2}", mes):
            raise ValueError("mês inválido")
        self._dados[cliente][mes] += minutos

    def total_cliente(self, cliente: str) -> int:
        return sum(self._dados.get(cliente, {}).values())

    def total_mes(self, mes: str) -> int:
        total = 0
        for cliente_dados in self._dados.values():
            total += cliente_dados.get(mes, 0)
        return total

    def ranking_mes(self, mes: str) -> list[tuple[str, int]]:
        ranking = []
        for cliente, meses in self._dados.items():
            minutos = meses.get(mes, 0)
            if minutos > 0:
                ranking.append((cliente, minutos))
        ranking.sort(key=lambda x: (-x[1], x[0]))
        return ranking

class ReputacaoUsuario:
    def __init__(self):
        self._up = 0
        self._down = 0

    def registrar_voto(self, tipo: str) -> None:
        if tipo not in ('up', 'down'):
            raise ValueError("Tipo de voto inválido. Use 'up' ou 'down'.")
        if tipo == 'up':
            self._up += 1
        else:
            self._down += 1

    def calcular_score(self) -> float:
        total = self._up + self._down + 1
        return (self._up - self._down) / total

class TabelaFrete:
    def __init__(self):
        self._faixas = []

    def adicionar_faixa(self, limite_ate_kg: float, preco_fixo: float, preco_por_kg_excedente: float) -> None:
        if limite_ate_kg <= 0:
            raise ValueError("limite_ate_kg deve ser positivo")
        if preco_fixo < 0:
            raise ValueError("preco_fixo não pode ser negativo")
        if preco_por_kg_excedente < 0:
            raise ValueError("preco_por_kg_excedente não pode ser negativo")
        if self._faixas and limite_ate_kg <= self._faixas[-1][0]:
            raise ValueError("limite_ate_kg deve ser maior que o limite da faixa anterior")
        self._faixas.append((limite_ate_kg, preco_fixo, preco_por_kg_excedente))

    def calcular_frete(self, peso: float) -> float:
        if not self._faixas:
            raise ValueError("nenhuma faixa cadastrada")
        if peso < 0:
            raise ValueError("peso não pode ser negativo")
        for limite_ate_kg, preco_fixo, preco_por_kg_excedente in self._faixas:
            if peso <= limite_ate_kg:
                return preco_fixo + max(0.0, peso - limite_ate_kg) * preco_por_kg_excedente
        # Se o peso exceder todas as faixas, usa a última faixa
        limite_ate_kg, preco_fixo, preco_por_kg_excedente = self._faixas[-1]
        return preco_fixo + (peso - limite_ate_kg) * preco_por_kg_excedente

    def listar_faixas(self) -> list[tuple[float, float, float]]:
        return self._faixas.copy()

    def remover_faixa(self, indice: int) -> None:
        if not 0 <= indice < len(self._faixas):
            raise ValueError("índice inválido")
        del self._faixas[indice]

class Elevador:
    def __init__(self, capacidade: int, total_andares: int):
        if capacidade <= 0:
            raise ValueError("Capacidade deve ser positiva")
        if total_andares <= 0:
            raise ValueError("Total de andares deve ser positivo")
        self._capacidade = capacidade
        self._total_andares = total_andares
        self._andar_atual = 0
        self._passageiros = 0

    def entrar(self, qtd: int) -> None:
        if qtd < 0:
            raise ValueError("Quantidade não pode ser negativa")
        if self._passageiros + qtd > self._capacidade:
            raise ValueError("Excede a capacidade do elevador")
        self._passageiros += qtd

    def sair(self, qtd: int) -> None:
        if qtd < 0:
            raise ValueError("Quantidade não pode ser negativa")
        if qtd > self._passageiros:
            raise ValueError("Não há passageiros suficientes para sair")
        self._passageiros -= qtd

    def subir(self) -> None:
        if self._andar_atual < self._total_andares - 1:
            self._andar_atual += 1

    def descer(self) -> None:
        if self._andar_atual > 0:
            self._andar_atual -= 1

    def status(self) -> tuple[int, int]:
        return (self._andar_atual, self._passageiros)

def merge_two(list1, list2):
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("Ambos os argumentos devem ser listas")
    i = j = 0
    merged = []
    while i < len(list1) and j < len(list2):
        try:
            if list1[i] <= list2[j]:
                merged.append(list1[i])
                i += 1
            else:
                merged.append(list2[j])
                j += 1
        except TypeError:
            raise TypeError("Elementos não comparáveis entre si")
    merged.extend(list1[i:])
    merged.extend(list2[j:])
    return merged


def merge_many(lists):
    try:
        iterator = iter(lists)
    except TypeError:
        raise TypeError("O argumento deve ser um iterável de listas")
    result = []
    for lst in iterator:
        if not isinstance(lst, list):
            raise TypeError("Todos os elementos do iterável devem ser listas")
        result = merge_two(result, lst)
    return result

import calendar
from typing import Dict, List, Tuple


class VencimentosMensais:
    def __init__(self, contas: Dict[str, int]) -> None:
        self._contas: Dict[str, int] = {}
        for nome, dia in contas.items():
            if not isinstance(dia, int) or not (1 <= dia <= 31):
                raise ValueError(f"Dia de vencimento inválido: {dia}")
            self._contas[nome] = dia

    def contas_no_mes(self, mes: int, ano: int) -> List[Tuple[str, int]]:
        if not (1 <= mes <= 12):
            raise ValueError("Mês inválido")
        _, ultimo_dia = calendar.monthrange(ano, mes)
        resultado = [
            (nome, dia) for nome, dia in self._contas.items() if dia <= ultimo_dia
        ]
        resultado.sort(key=lambda x: (x[1], x[0]))
        return resultado

    def adicionar_conta(self, nome: str, dia: int) -> None:
        if not isinstance(dia, int) or not (1 <= dia <= 31):
            raise ValueError(f"Dia de vencimento inválido: {dia}")
        self._contas[nome] = dia

    def remover_conta(self, nome: str) -> None:
        if nome not in self._contas:
            raise KeyError(nome)
        del self._contas[nome]

import math


def resolver_equacao(a: float, b: float, c: float) -> tuple[float, ...]:
    if a == 0:
        if b == 0:
            raise ValueError("Equação degenerada: a e b não podem ser ambos zero")
        return (-c / b,)

    discriminante = b * b - 4 * a * c
    if discriminante < 0:
        raise ValueError("Discriminante negativo: equação não possui raízes reais")

    sqrt_d = math.sqrt(discriminante)
    x1 = (-b - sqrt_d) / (2 * a)
    x2 = (-b + sqrt_d) / (2 * a)
    return tuple(sorted((x1, x2)))

def parse_http_headers(raw: str) -> dict[str, str]:
    """Parse raw HTTP headers into a normalized dictionary.

    Args:
        raw: String containing raw HTTP headers, possibly with continuation lines.

    Returns:
        Dictionary mapping lowercased header names to their unfolded values.

    Raises:
        ValueError: If the first non-empty line does not contain a colon.
    """
    lines = raw.splitlines()
    result: dict[str, str] = {}
    current_key: str | None = None
    current_value: str = ""
    started = False

    for line in lines:
        if not started:
            if line == "":
                continue
            started = True
            if ":" not in line:
                raise ValueError("Invalid header line: missing colon")
        else:
            if line == "":
                break

        if line.startswith((" ", "\t")):
            if current_key is None:
                raise ValueError("Continuation line without preceding header")
            current_value += " " + line.lstrip()
        else:
            if current_key is not None:
                result[current_key] = current_value.strip()
            if ":" not in line:
                raise ValueError("Invalid header line: missing colon")
            key, value = line.split(":", 1)
            current_key = key.strip().lower()
            current_value = value.strip()

    if current_key is not None:
        result[current_key] = current_value.strip()

    return result

import time


class CacheComExpiracao:
    def __init__(self):
        self._dados = {}

    def definir(self, chave, valor, ttl):
        if not isinstance(ttl, int) or ttl <= 0:
            raise ValueError("TTL deve ser um inteiro positivo")
        expiracao = time.time() + ttl
        self._dados[chave] = (valor, expiracao)

    def obter(self, chave):
        if chave not in self._dados:
            return None
        valor, expiracao = self._dados[chave]
        if time.time() > expiracao:
            del self._dados[chave]
            return None
        return valor

    def remover(self, chave):
        if chave in self._dados:
            del self._dados[chave]
            return True
        return False

    def limpar_expirados(self):
        agora = time.time()
        chaves_expiradas = [k for k, (_, exp) in self._dados.items() if agora > exp]
        for k in chaves_expiradas:
            del self._dados[k]
        return len(chaves_expiradas)

def arredondar_para_multiplo(valor, multiplo):
    if not isinstance(valor, (int, float)) or not isinstance(multiplo, (int, float)):
        raise TypeError("valor e multiplo devem ser numéricos")
    if multiplo == 0:
        raise ValueError("multiplo não pode ser zero")
    m = abs(multiplo)
    resto = valor % m
    meio = m / 2
    if resto > meio or (resto == meio and valor >= 0):
        return valor + (m - resto)
    elif resto == meio and valor < 0:
        return valor - (m - resto)
    else:
        return valor - resto

