class NestedFlattener:
    def __init__(self):
        self._last_depth = 0

    def flatten(self, nested_list):
        if not isinstance(nested_list, list):
            raise TypeError("O argumento deve ser uma lista")
        self._last_depth = 0
        result = []
        self._flatten_recursive(nested_list, 1, result)
        return result

    def _flatten_recursive(self, current_list, current_depth, result):
        if current_depth > self._last_depth:
            self._last_depth = current_depth
        for item in current_list:
            if isinstance(item, list):
                self._flatten_recursive(item, current_depth + 1, result)
            else:
                result.append(item)

    def depth(self):
        return self._last_depth

def classificar_acesso(ip: str) -> str:
    partes = ip.split('.')
    if len(partes) != 4:
        raise ValueError("Formato IPv4 inválido")

    octetos = []
    for parte in partes:
        if not parte.isdigit():
            raise ValueError("Octeto não numérico")
        if len(parte) > 1 and parte[0] == '0':
            raise ValueError("Zeros à esquerda não permitidos")
        valor = int(parte)
        if valor < 0 or valor > 255:
            raise ValueError("Octeto fora do intervalo 0-255")
        octetos.append(valor)

    primeiro, segundo = octetos[0], octetos[1]

    if primeiro == 127:
        return "loopback"
    if primeiro == 10:
        return "privado"
    if primeiro == 172 and 16 <= segundo <= 31:
        return "privado"
    if primeiro == 192 and segundo == 168:
        return "privado"

    return "publico"

class AdivinhacaoJogo:
    def __init__(self, segredo: int, max_tentativas: int):
        if not (1 <= segredo <= 100):
            raise ValueError("Segredo deve estar entre 1 e 100")
        if max_tentativas <= 0:
            raise ValueError("Máximo de tentativas deve ser positivo")
        self._segredo = segredo
        self._max_tentativas = max_tentativas
        self._tentativas_usadas = 0
        self._acabou = False

    def tentar(self, palpite: int):
        if self._acabou:
            raise ValueError("Jogo já terminou")
        if not (1 <= palpite <= 100):
            raise ValueError("Palpite deve estar entre 1 e 100")
        self._tentativas_usadas += 1
        if palpite == self._segredo:
            self._acabou = True
            return ("acertou", 0)
        elif self._tentativas_usadas >= self._max_tentativas:
            self._acabou = True
            return ("sem_tentativas", abs(palpite - self._segredo))
        elif palpite > self._segredo:
            return ("menor", abs(palpite - self._segredo))
        else:
            return ("maior", abs(palpite - self._segredo))

    def tentativas_restantes(self):
        return max(0, self._max_tentativas - self._tentativas_usadas)

def build_filter_clause(filters):
    if not isinstance(filters, dict):
        raise TypeError("filters deve ser um dicionário")

    conditions = []
    params = []

    for key, value in filters.items():
        if value is None:
            continue

        if key.endswith('__in'):
            column = key[:-4]
            if not isinstance(value, (list, tuple, set)):
                raise ValueError(f"Valor para {key} deve ser lista, tupla ou set")
            if not value:
                continue
            placeholders = ', '.join(['%s'] * len(value))
            conditions.append(f"{column} IN ({placeholders})")
            params.extend(value)
        elif key.endswith('__gt'):
            column = key[:-4]
            conditions.append(f"{column} > %s")
            params.append(value)
        elif key.endswith('__lt'):
            column = key[:-4]
            conditions.append(f"{column} < %s")
            params.append(value)
        else:
            conditions.append(f"{key} = %s")
            params.append(value)

    if not conditions:
        return "", []

    where_clause = "WHERE " + " AND ".join(conditions)
    return where_clause, params

