    i = j = 0
    n1 = len(list1)
    n2 = len(list2)
    while i < n1 and j < n2:
        try:
            if list1[i] <= list2[j]:
                resultado.append(list1[i])
                i += 1
            else:
                resultado.append(list2[j])
                j += 1
        except TypeError:
            raise TypeError("os elementos das listas devem ser comparáveis")
    while i < n1:
        try:
            resultado.append(list1[i])
        except TypeError:
            raise TypeError("os elementos das listas devem ser comparáveis")
        i += 1
    while j < n2:
