MORSE_PARA_LETRA = {morse: letra for letra, morse in LETRA_PARA_MORSE.items()}

def texto_para_morse(texto):
    if not isinstance(texto, str):
        raise ValueError("texto deve ser uma string")
    for caractere in texto:
        if caractere != ' ' and caractere.upper() not in LETRA_PARA_MORSE:
            raise ValueError("caractere não permitido: " + caractere)
    palavras = texto.split()
    resultado = []
    for palavra in palavras:
        letras = []
        for caractere in palavra:
            letras.append(LETRA_PARA_MORSE[caractere.upper()])
        resultado.append(' '.join(letras))
    return '   '.join(resultado)

def morse_para_texto(morse):
    if not isinstance(morse, str):
        raise ValueError("morse deve ser uma string")
    if morse == '':
        return ''
    if morse[0] == ' ' or morse[-1] == ' ':
        raise ValueError("espaçamento incorreto")
    if '   ' in morse:
        partes = morse.split('   ')
        for parte in partes:
            if parte == '' or '  ' in parte:
                raise ValueError("espaçamento incorreto")
    else:
        partes = [morse]
    texto = []
    for parte in partes:
        letras = parte.split(' ')
        palavra = []
        for codigo in letras:
            if codigo == '' or codigo not in MORSE_PARA_LETRA:
                raise ValueError("sequência Morse inválida")
            palavra.append(MORSE_PARA_LETRA[codigo])
        texto.append(''.join(palavra))
    return ' '.join(texto)

