from math import gcd

def multiplica_fracao(fracao1, fracao2):
    num1, den1 = fracao1
    num2, den2 = fracao2
    if den1 == 0 or den2 == 0:
        raise ValueError("denominador nao pode ser zero")
    num = num1 * num2
    den = den1 * den2
    if den < 0:
        num = -num
        den = -den
    divisor = gcd(abs(num), den)
    return (num // divisor, den // divisor)

