        self._disponiveis.remove(livro)
        self._emprestados[livro] = usuario
        self._ativos_por_usuario[usuario] = self._ativos_por_usuario.get(usuario, 0) + 1

    def devolver(self, livro):
        if livro not in self._emprestados:
            raise ValueError("livro não está emprestado")
        usuario = self._emprestados.pop(livro)
        self._disponiveis.append(livro)
        self._disponiveis.sort()
        self._ativos_por_usuario[usuario] -= 1
        if self._ativos_por_usuario[usuario] == 0:
            del self._ativos_por_usuario[usuario]

    def disponiveis(self):
        return list(self._disponiveis)

def contar_caminhos(linhas, colunas):
    if not isinstance(linhas, int) or isinstance(linhas, bool) or linhas < 1:
        raise ValueError("linhas invalidas")
    if not isinstance(colunas, int) or isinstance(colunas, bool) or colunas < 1:
        raise ValueError("colunas invalidas")
    caminhos = [[1] * colunas for _ in range(linhas)]
    for i in range(1, linhas):
        for j in range(1, colunas):
            caminhos[i][j] = caminhos[i - 1][j] + caminhos[i][j - 1]
    return caminhos[linhas - 1][colunas - 1]

def complemento_reverso(fita):
    if not isinstance(fita, str) or any(b not in "ATCG" for b in fita):
        raise ValueError("fita invalida")
    pares = {"A": "T", "T": "A", "C": "G", "G": "C"}
    return "".join(pares[b] for b in reversed(fita))


def contar_bases(fita):
    if not isinstance(fita, str) or any(b not in "ATCG" for b in fita):
        raise ValueError("fita invalida")
    contagem = {"A": 0, "T": 0, "C": 0, "G": 0}
    for b in fita:
        contagem[b] += 1
    return contagem

def segundo_maior_distinto(valores):
    if not isinstance(valores, list):
        raise ValueError("entrada deve ser uma lista")
    distintos = sorted(set(valores), reverse=True)
    if len(distintos) < 2:
        return None
    return distintos[1]


def posicao_segundo_maior(valores):
    if not isinstance(valores, list):
        raise ValueError("entrada deve ser uma lista")
    alvo = segundo_maior_distinto(valores)
    if alvo is None:
        return -1
    return valores.index(alvo)

def combinar_somas(a, b):
    if not isinstance(a, dict) or not isinstance(b, dict):
        raise TypeError("argumentos devem ser dicionarios")
    resultado = {}
    for chave, valor in a.items():
        if not isinstance(valor, (int, float)) or isinstance(valor, bool):
            raise ValueError("valores devem ser numeros")
        resultado[chave] = valor
    for chave, valor in b.items():
        if not isinstance(valor, (int, float)) or isinstance(valor, bool):
            raise ValueError("valores devem ser numeros")
        if chave in resultado:
            resultado[chave] = resultado[chave] + valor
        else:
            resultado[chave] = valor
    return resultado

class InversorBlocos:
    def __init__(self, itens):
        self.itens = list(itens)

    def inverter(self, k):
        if k <= 0:
            raise ValueError("k deve ser positivo")
        blocos = [self.itens[i:i + k] for i in range(0, len(self.itens), k)]
        incompleto = []
        if blocos and len(blocos[-1]) < k:
            incompleto = blocos.pop()
        resultado = []
        for bloco in reversed(blocos):
            resultado.extend(bloco)
        resultado.extend(incompleto)
        return resultado

    def restaurar(self):
        return list(self.itens)

def avalia_rpn(expressao):
    if not expressao or not expressao.strip():
        raise ValueError("expressao vazia")
    pilha = []
    for token in expressao.split():
        if token in ("+", "-", "*", "/"):
            if len(pilha) < 2:
                raise ValueError("faltam operandos")
            b = pilha.pop()
            a = pilha.pop()
            if token == "+":
                pilha.append(a + b)
            elif token == "-":
                pilha.append(a - b)
            elif token == "*":
                pilha.append(a * b)
            else:
                if b == 0:
                    raise ValueError("divisao por zero")
                quociente = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    quociente = -quociente
                pilha.append(quociente)
        else:
            try:
                pilha.append(int(token))
            except ValueError:
                raise ValueError("token invalido: " + token)
    if len(pilha) != 1:
        raise ValueError("expressao mal formada")
    return pilha[0]

def capitalizar_palavras(texto):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    if texto.strip() == "":
        raise ValueError("texto não pode ser vazio")
    resultado = []
    inicio_palavra = True
    for caractere in texto:
        if caractere == " ":
            resultado.append(caractere)
            inicio_palavra = True
        else:
            if inicio_palavra:
                resultado.append(caractere.upper())
                inicio_palavra = False
            else:
                resultado.append(caractere)
    return "".join(resultado)

class MesaBaralho:
    def __init__(self, cartas):
        if not cartas:
            raise ValueError("monte vazio")
        self._maos = {1: [], 2: []}
        for i, carta in enumerate(cartas):
            self._maos[1 if i % 2 == 0 else 2].append(carta)

    def mao(self, jogador):
        if jogador not in (1, 2):
            raise ValueError("jogador invalido")
        return list(self._maos[jogador])

    def comparar(self):
        soma1 = sum(self._maos[1])
        soma2 = sum(self._maos[2])
        if soma1 > soma2:
            return "jogador1"
        if soma2 > soma1:
            return "jogador2"
        return "empate"

def rotacionar90(matriz):
    if not matriz or any(len(linha) != len(matriz) for linha in matriz):
        raise ValueError("matriz invalida")
    n = len(matriz)
    return [[matriz[n - 1 - j][i] for j in range(n)] for i in range(n)]
